/**
 * Player remove route — 从队列中移除指定索引的曲目。
 *
 * 接收 `{ index }`，调用 player-state.removeFromQueue 移除。
 * 移除当前播放项时自动切到下一首。返回 400 如果 index 缺失/非数字。
 */
import { removeFromQueue } from '@/server/player/state';
import { playerPayload } from '@/server/player/payload';
import { ok, fail } from '@/server/http';

export async function POST(request: Request) {
	let body: { index?: unknown };
	try {
		body = await request.json();
	} catch {
		return fail('Invalid JSON body', 400);
	}

	const index = typeof body.index === 'number' ? body.index : Number.parseInt(String(body.index ?? ''), 10);
	if (!Number.isInteger(index)) {
		return fail('index must be an integer', 400);
	}

	// 队列整理不算"播放事件"，刻意不写 interaction log（`recent_plays` 只认
	// play/next/jump，写了也是噪声）。
	return ok(playerPayload(removeFromQueue(index), { withQueue: true }));
}
